  "selection_reason": "user-controlled property name -> embedded in property access code -> potential prototype pollution if not properly escaped",
  "security_relevance_score": 0.7,
  "code_context": "1: 'use strict';
2: 
3: var stringify = require('../../utils/string').stringify;
4: var getSafeProperty = require('../../utils/customs').getSafeProperty;
5: 
6: function factory (type, config, load, typed) {
7:   var register = load(require('./compile')).register;
8:   var compile = load(require('./compile')).compile;
9:   var Node = load(require('./Node'));
10:   var access = load(require('./utils/access'));
11: 
12:   /**
13:    * @constructor AccessorNode
14:    * @extends {Node}
15:    * Access an object property or get a matrix subset
16:    *
17:    * @param {Node} object                 The object from which to retrieve
18:    *                                      a property or subset.
19:    * @param {IndexNode} index             IndexNode containing ranges
20:    */
21:   function AccessorNode(object, index) {
22:     if (!(this instanceof AccessorNode)) {
23:       throw new SyntaxError('Constructor must be called with the new operator');
24:     }
25: 
26:     if (!(object && object.isNode)) {
27:       throw new TypeError('Node expected for parameter "object"');
28:     }
29:     if (!(index && index.isIndexNode)) {
30:       throw new TypeError('IndexNode expected for parameter "index"');
31:     }
32: 
33:     this.object = object || null;
34:     this.index = index;
35: 
36:     // readonly property name
37:     Object.defineProperty(this, 'name', {
38:       get: function () {
39:         if (this.index) {
40:           return (this.index.isObjectProperty())
41:               ? this.index.getObjectProperty()
42:               : '';
43:         }
44:         else {
45:           return this.object.name || '';
46:         }
47:       }.bind(this),
48:       set: function () {
49:         throw new Error('Cannot assign a new name, name is read-only');
50:       }
51:     });
52:   }
53: 
54:   AccessorNode.prototype = new Node();
55: 
56:   AccessorNode.prototype.type = 'AccessorNode';
57: 
58:   AccessorNode.prototype.isAccessorNode = true;
59: 
60:   /**
61:    * Compile the node to javascript code
62:    * @param {AccessorNode} node  Node to be compiled
63:    * @param {Object} defs     Object which can be used to define functions
64:    *                          or constants globally available for the compiled
65:    *                          expression
66:    * @param {Object} args     Object with local function arguments, the key is
67:    *                          the name of the argument, and the value is `true`.
68:    *                          The object may not be mutated, but must be
69:    *                          extended instead.
70:    * @return {string} js
71:    * @private
72:    */
73:   function compileAccessorNode(node, defs, args) {
74:     defs.access = access;
75:     defs.getSafeProperty = getSafeProperty;
76: 
77:     var object = compile(node.object, defs, args);
78:     var index = compile(node.index, defs, args);
79: 
80:     if (node.index.isObjectProperty()) {
81:       var jsProp = stringify(node.index.getObjectProperty());
82:       return 'getSafeProperty(' + object + ', ' + jsProp + ')';
83:     }
84:     else if (node.index.needsSize()) {
85:       // if some parameters use the 'end' parameter, we need to calculate the size
86:       return '(function () {' +
87:           '  var object = ' + object + ';' +
88:           '  var size = math.size(object).valueOf();' +
89:           '  return access(object, ' + index + ');' +
90:           '})()';
91:     }
92:     else {
93:       return 'access(' + object + ', ' + index + ')';
94:     }
95:   }
96: 
97:   // register the compile function
98:   register(AccessorNode.prototype.type, compileAccessorNode);
99: 
100:   /**
101:    * Execute a callback for each of the child nodes of this node
102:    * @param {function(child: Node, path: string, parent: Node)} callback
103:    */
104:   AccessorNode.prototype.forEach = function (callback) {
105:     callback(this.object, 'object', this);
106:     callback(this.index, 'index', this);
107:   };
108: 
109:   /**
110:    * Create a new AccessorNode having it's childs be the results of calling
111:    * the provided callback function for each of the childs of the original node.
112:    * @param {function(child: Node, path: string, parent: Node): Node} callback
113:    * @returns {AccessorNode} Returns a transformed copy of the node
114:    */
115:   AccessorNode.prototype.map = function (callback) {
116:     return new AccessorNode(
117:         this._ifNode(callback(this.object, 'object', this)),
118:         this._ifNode(callback(this.index, 'index', this))
119:     );
120:   };
121: 
122:   /**
123:    * Create a clone of this node, a shallow copy
124:    * @return {AccessorNode}
125:    */
126:   AccessorNode.prototype.clone = function () {
127:     return new AccessorNode(this.object, this.index);
128:   };
129: 
130:   /**
131:    * Get string representation
132:    * @param {Object} options
133:    * @return {string}
134:    */
135:   AccessorNode.prototype._toString = function (options) {
136:     var object = this.object.toString(options);
137:     if (needParenthesis(this.object)) {
138:       object = '(' + object + ')';
139:     }
140: 
141:     return object + this.index.toString(options);
142:   };
143: 
144:   /**
145:    * Get LaTeX representation
146:    * @param {Object} options
147:    * @return {string}
148:    */
149:   AccessorNode.prototype._toTex = function (options) {
150:     var object = this.object.toTex(options);
151:     if (needParenthesis(this.object)) {
152:       object = '\\left(' + object + '\\right)';
153:     }
154: 
155:     return object + this.index.toTex(options);
156:   };
157: 
158:   /**
159:    * Are parenthesis needed?
160:    * @private
161:    */
162:   function needParenthesis(node) {
163:     // TODO: maybe make a method on the nodes which tells whether they need parenthesis?
164:     return !(node.isAccessorNode || node.isArrayNode || node.isConstantNode
165:         || node.isFunctionNode || node.isObjectNode || node.isParenthesisNode
166:         || node.isSymbolNode);
167:   }
168: 
169:   return AccessorNode;
170: }
171: 
172: exports.name = 'AccessorNode';
173: exports.path = 'expression.node';
174: exports.factory = factory;",
  "source_summary": "Property name comes from node.index.getObjectProperty() which extracts value from ConstantNode dimensions in IndexNode. User input flows through expression parsing to create these nodes.",
